sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    const requestBody = request.body.nextEntry();
    gs.info(`x_neyu_google_nyu/drive_transfer_callback request recieved` +
        ` Parameters: ${JSON.stringify(requestBody, null, 2)}`);

    const fields = [
        "sn_ticket_number",
        "sn_status",
        "sn_recipient_email",
        "sn_old_owner",
        "sn_success_count",
        "sn_failure_count",
        "sn_success_list",
        "sn_failure_list"
    ];

    const missingParams = new global.ArrayUtil().diff(
        fields,
        Object.keys(requestBody)
    );

    if (Array.isArray(missingParams) && missingParams.length > 0) {
        gs.error(`Missing Parameters: ${missingParams.join(", ")}`);
        response.setError(
            new sn_ws_err.BadRequestError(
                `Missing required fields: ${missingParams.join(", ")}`
            )
        );
        return;
    }

    const ritmGR = new GlideRecord("sc_req_item");
    if (!ritmGR.get("number", requestBody["sn_ticket_number"])) {
        gs.error(`Unable to find requested item: ${requestBody["sn_ticket_number"]}`);
        response.setError(
            new sn_ws_err.NotFoundError(
                `Unable to find Requested Item: ${requestBody["sn_ticket_number"]}`
            )
        );
        return;
    }

	const flowContext = new GlideRecord("sys_flow_context");
	flowContext.addQuery("source_table", ritmGR.getTableName());
	flowContext.addQuery("source_record", ritmGR.getValue("sys_id"));
	flowContext.query();

	if (!flowContext.next()) {
		response.setError(
            new sn_ws_err.NotFoundError(
                `Unable to find executing flow for ${ritmGR.getValue("number")}`
            )
        );
        return;
	}

    const subflow = new GlideRecord("sys_flow_context");
	subflow.addQuery("source_table", "sys_flow_context");
	subflow.addQuery("source_record", flowContext.getValue("sys_id"));
	subflow.addQuery("state", "WAITING");
	subflow.query();

    if (!subflow.next()) {
        response.setError(
            new sn_ws_err.NotFoundError(
                `Unable to find executing flow for ${ritmGR.getValue("number")}`
            )
        );
        return;
    }

    try {
        var result = sn_fd.FlowAPI.sendMessage(
            subflow.getValue("sys_id"),
            "DRIVE_FILE_TRANSFER_CALLBACK",
            JSON.stringify(requestBody)
        );
        gs.debug(`Result: ${result}`);
    } catch (ex) {
        gs.error("Drive Transfer Callback error: " + ex);
        const err = new sn_ws_err.ServiceError();
        err.setStatus(500);
        err.setMessage(ex + "");
        response.setError(err);
        return;
    }

    gs.info(`Notified Flow ${subflow.getValue("sys_id")} for ` +
        `${ritmGR.getValue("sys_id")} returning success`);
    response.setStatus(200);

})(request, response);
